import React, { useState } from 'react';
import RadioPlayer from './components/RadioPlayer';
import StreamConfig from './components/StreamConfig';

function App() {
  const [streamUrl, setStreamUrl] = useState('');
  const [isPlaying, setIsPlaying] = useState(false);
  const [nowPlaying, setNowPlaying] = useState('Radio Stream');
  const [connectionStatus, setConnectionStatus] = useState('disconnected');

  // Working radio stream URLs
  const defaultStreams = [
    { 
      name: 'Radio Paradise', 
      url: 'https://stream.radioparadise.com/aac-128',
      description: 'Eclectic mix of music'
    },
    { 
      name: 'SomaFM Groove Salad', 
      url: 'https://ice1.somafm.com/groovesalad-128-mp3',
      description: 'Ambient beats and grooves'
    },
    { 
      name: 'SomaFM Drone Zone', 
      url: 'https://ice1.somafm.com/dronezone-128-mp3',
      description: 'Atmospheric textures and beats'
    },
    { 
      name: 'SomaFM Lush', 
      url: 'https://ice1.somafm.com/lush-128-mp3',
      description: 'Female vocals with jazz and soul'
    }
  ];

  const handleStreamChange = (url) => {
    setStreamUrl(url);
    setIsPlaying(false);
    setConnectionStatus('disconnected');
  };

  const handlePlayStateChange = (playing) => {
    setIsPlaying(playing);
    setConnectionStatus(playing ? 'connected' : 'disconnected');
  };

  const handleNowPlayingChange = (title) => {
    setNowPlaying(title);
  };

  const handleConnectionStatusChange = (status) => {
    setConnectionStatus(status);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <header className="text-center mb-8">
          <h1 className="text-4xl md:text-6xl font-bold text-white mb-4">
            Audio Streamer
          </h1>
          <p className="text-xl text-gray-300 max-w-2xl mx-auto">
            Stream your favorite online radio stations with a minimal, fast, and responsive interface
          </p>
        </header>

        {/* Main Content */}
        <div className="max-w-4xl mx-auto">
          {/* Stream Configuration */}
          <StreamConfig 
            defaultStreams={defaultStreams}
            onStreamChange={handleStreamChange}
            currentStream={streamUrl}
          />

          {/* Radio Player */}
          {streamUrl && (
            <RadioPlayer
              streamUrl={streamUrl}
              onPlayStateChange={handlePlayStateChange}
              onNowPlayingChange={handleNowPlayingChange}
              onConnectionStatusChange={handleConnectionStatusChange}
              isPlaying={isPlaying}
              nowPlaying={nowPlaying}
              connectionStatus={connectionStatus}
            />
          )}

                  {/* Status Display */}
        <div className="mt-6 text-center space-y-3">
          <div className="inline-flex items-center space-x-2 px-4 py-2 rounded-full bg-gray-800 border border-gray-700">
            <div className={`w-3 h-3 rounded-full ${
              connectionStatus === 'connected' ? 'bg-green-500' :
              connectionStatus === 'connecting' ? 'bg-yellow-500' :
              'bg-red-500'
            }`}></div>
            <span className="text-sm text-gray-300 capitalize">
              {connectionStatus}
            </span>
          </div>

          {!streamUrl && (
            <div className="text-sm text-gray-400">
              Select a radio stream above to start listening
            </div>
          )}
        </div>
        </div>

        {/* Footer */}
        <footer className="mt-16 text-center text-gray-400">
          <p className="text-sm">
            Designed for Bib Kreyòl app integration • Built with React & Tailwind CSS
          </p>
        </footer>
      </div>
    </div>
  );
}

export default App;
